import React, { forwardRef, useCallback, useEffect, useRef } from 'react';
import { useIntl } from 'react-intl';
import styled, { CSSObject } from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Easings from '@dynatrace/strato-design-tokens/easings';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Timings from '@dynatrace/strato-design-tokens/timings';

import { _usePanelsContext } from './hooks/_usePanelsContext.js';
import { _useParentPanelContext } from './hooks/_useParentPanelContext.js';
import { useResizable } from './hooks/useResizable.js';
import { PanelsActions } from './types/panels-state.js';
import { anyUnitToFractions } from './utils/units.js';
import { useFocusRing } from '../../../core/hooks/useFocusRing.js';
import { useMergeRefs } from '../../../core/hooks/useMergeRefs.js';
import type { DataTestId } from '../../../core/types/data-props.js';
import type { StylingProps } from '../../../core/types/styling-props.js';

export const RESIZE_HANDLE_SIZE = 8;

//#region Styles
const StyledResizer = /* @__PURE__ */ styled.div<{
  $gridArea: string;
}>(({ $gridArea }) => ({
  gridArea: $gridArea,
  position: 'relative',
  display: 'flex',
  justifyContent: 'center',
  alignContent: 'center',
  flexWrap: 'wrap',
  width: '100%',
  height: '100%',
  borderRadius: Borders.Radius.Field.Default,

  touchAction: 'none',
}));

const StyledHandle = /* @__PURE__ */ styled.div<{
  $focusStyles: CSSObject;
}>(({ $focusStyles }) => ({
  touchAction: 'none',
  background: Colors.Border.Neutral.Default,
  cursor: 'col-resize',
  transition: `height ${Timings.Base.Default} ${Easings.FastInSlowOut}`,
  height: Spacings.Size36,
  /**
   * Since the focus-ring uses an inset box-shadow a 2px width is too small to
   * apply it to. With the 100% width it looks like an outside focus ring and fits neatly.
   */
  width: `${$focusStyles.boxShadow ? '100%' : '2px'}`,
  left: '3px',
  borderRadius: Borders.Radius.Field.Default,
  backgroundColor: Colors.Border.Neutral.Accent,
  ...$focusStyles,

  '&:focus, &:hover': {
    height: Spacings.Size48,
    backgroundColor: Colors.Border.Neutral.AccentHover,
  },

  // The resizing ref is applied to the actual handle to manage the focus state by the ref.
  // However, this would make only the handle resizable and not the whole separator, hence the after element.
  '&:after': {
    content: '""',
    height: '100%',
    width: '100%',
    display: 'block',
    position: 'absolute',
    top: 0,
    left: '50%',
    transform: 'translateX(-50%)',
    userSelect: 'none',
  },
}));

//#endregion

//#region Props
/** @internal */
export type ResizerProps = {
  name: string;
  order: number;
  resizable: boolean;
} & StylingProps &
  DataTestId;
//#endregion

/**
 * The `Resizer` component must be rendered between `Panel`s to ensure correct calculations
 * and provide a handle for the user to grab for resizing panels.
 * @internal
 */
export const Resizer = React.memo(
  forwardRef<HTMLDivElement, ResizerProps>((props, forwardedRef) => {
    const {
      name,
      order,
      style,
      resizable,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: ResizerProps = props;
    const intl = useIntl();

    const { dispatch } = _usePanelsContext();
    const { parentPanelWidth, sizes, sortedPanels } = _useParentPanelContext();

    const { focusStyles, focusProps } = useFocusRing();

    const containerRef = useRef<HTMLDivElement | null>(null);
    const { resizerRef } = useResizable({
      order,
    });

    const calculateHandlePosition = useCallback(() => {
      const panelsBeforeHandle = sortedPanels.slice(0, order + 1);
      let handlePosition = 0;
      for (const panel of panelsBeforeHandle) {
        handlePosition +=
          anyUnitToFractions(sizes[panel.name], parentPanelWidth, 0) || 0;
      }

      return Math.ceil(handlePosition);
      // Excluding sortedPanels to avoid additional re-renders.
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [order, parentPanelWidth, sizes]);

    // Current position of the resize handle in the container to populate aria-valuenow.
    const currentPosition = calculateHandlePosition();

    const mergedRef = useMergeRefs([forwardedRef, resizerRef]);

    useEffect(() => {
      dispatch({
        type: PanelsActions.ADDRESIZEHANDLE,
        payload: {
          name,
          order,
        },
      });

      return () => {
        dispatch({
          type: PanelsActions.REMOVERESIZEHANDLE,
          payload: {
            name,
          },
        });
      };
      // Only needed for cleanup to remove handle when unmounting to enable conditional rendering
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    return (
      <StyledResizer
        ref={containerRef}
        className={consumerClassName}
        style={{ ...style, ...consumerStyle }}
        data-testid={dataTestId}
        $gridArea={name}
        {...(!resizable && { role: 'separator' })}
        {...remainingProps}
      >
        {resizable && (
          /* eslint-disable jsx-a11y/role-supports-aria-props */
          <>
            <StyledHandle
              tabIndex={0}
              ref={mergedRef}
              data-testid="panel-resize-handle"
              role="separator"
              aria-valuenow={currentPosition}
              aria-label={intl.formatMessage(
                {
                  defaultMessage:
                    'Button "{name}" for resizing the corresponding panels.',
                  id: '5mSdhujC0nLrjORk',
                  description: 'Aria label for the panel resizer.',
                },
                { name },
              )}
              aria-describedby="resize-handle-description"
              $focusStyles={focusStyles}
              {...focusProps}
            />
            <p id="resize-handle-description" hidden>
              {intl.formatMessage({
                defaultMessage:
                  'The min and max value represent the leftmost / rightmost border of the container element. The valuenow equals the percentage position of the resize handle inside the container. It can not necessarily reach the min / max position.',
                id: 'O4kuGPSNH0oBronn',
                description:
                  "Additional description for the resize handle's position.",
              })}
            </p>
          </>
          /* eslint-enable jsx-a11y/role-supports-aria-props */
        )}
      </StyledResizer>
    );
  }),
);
